#!/usr/bin/env node
// Generates app/public/test-fixtures/wave-bands.json — a deterministic Open-Meteo
// Marine response consumed via `?waveFixture=` (#1699, src/state/usePlanFlow.ts),
// so e2e never touches the marine API. Same lattice, start hour and length as
// gen-wind-fixture.mjs; regenerated by `pree2e` for the same horizon reason.
//
// Non-uniform on purpose, so the overlay can show every case:
// - Hs cycles through all five WMO bands by latitude row;
// - NULL_POINTS have an all-null series (no data, never calm);
// - direction (FROM, meteorological) and period vary by column.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const N_LATS = 14; // must match openMeteo.ts's LATS.length
const N_LONS = 23; // must match openMeteo.ts's LONS.length
const N_HOURS = 144; // FORECAST_DAYS (6) * 24
// One value inside each band: calm, smooth, slight, moderate, rough.
const BAND_HEIGHTS_M = [0.05, 0.3, 0.8, 1.8, 3.2];
// [latIdx, lonIdx] of the all-null points.
const NULL_POINTS = [
  [0, 0],
  [0, 1],
  [1, 0],
  [6, 11],
  [13, 22],
];

const startS = Math.floor(Date.now() / 1000 / 3600) * 3600; // current UTC hour, unix seconds
const time = Array.from({ length: N_HOURS }, (_, i) => startS + i * 3600);
const isNull = (lat, lon) => NULL_POINTS.some(([a, b]) => a === lat && b === lon);

const fixture = [];
for (let lat = 0; lat < N_LATS; lat++) {
  for (let lon = 0; lon < N_LONS; lon++) {
    const series = (v) => Array(N_HOURS).fill(isNull(lat, lon) ? null : v);
    fixture.push({
      hourly: {
        time,
        wave_height: series(BAND_HEIGHTS_M[lat % BAND_HEIGHTS_M.length]),
        wave_direction: series((lon * 16 + lat * 7) % 360),
        wave_period: series(2.5 + (lon % 6) * 0.75),
      },
    });
  }
}

const __dirname = dirname(fileURLToPath(import.meta.url));
const outPath = resolve(__dirname, '../public/test-fixtures/wave-bands.json');
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(fixture));

console.log(
  `wrote ${outPath} — ${fixture.length} points x ${N_HOURS} hours, ` +
    `${NULL_POINTS.length} all-null points, time[0]=${startS} (${new Date(startS * 1000).toISOString()})`,
);
